import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.Zh78JZbW.js";const m=JSON.parse('{"title":"Problèmes fréquents","description":"","frontmatter":{},"headers":[],"relativePath":"guide/depannage.md","filePath":"guide/depannage.md"}'),s={name:"guide/depannage.md"};function o(d,e,i,l,u,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="problemes-frequents" tabindex="-1">Problèmes fréquents <a class="header-anchor" href="#problemes-frequents" aria-label="Permalink to &quot;Problèmes fréquents&quot;">​</a></h1><p>Dans 9 cas sur 10, un souci vient d&#39;un mod : désactive le dernier mod ajouté et relance.</p><h2 id="quand-minecraft-plante" tabindex="-1">Quand Minecraft plante <a class="header-anchor" href="#quand-minecraft-plante" aria-label="Permalink to &quot;Quand Minecraft plante&quot;">​</a></h2><p>Kodus ouvre une fenêtre <strong>« Minecraft a planté »</strong> qui explique la cause en français et propose de corriger en un clic :</p><ul><li><strong>Il manque un mod</strong> : bouton pour l&#39;installer.</li><li><strong>Un mod n&#39;est pas fait pour ta version</strong>, ou <strong>deux mods sont incompatibles</strong> : bouton pour désactiver le mod en cause.</li><li><strong>Pas assez de mémoire</strong> : bouton pour changer la RAM.</li><li><strong>Loader trop ancien</strong> : bouton pour le mettre à jour.</li></ul><p>Après une correction, clique <strong>Relancer</strong>. Si la cause est inconnue, Kodus donne des conseils généraux et le bouton <strong>Copier le diagnostic</strong> pour demander de l&#39;aide.</p><h2 id="les-cas-courants" tabindex="-1">Les cas courants <a class="header-anchor" href="#les-cas-courants" aria-label="Permalink to &quot;Les cas courants&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problème</th><th>Quoi faire</th></tr></thead><tbody><tr><td>Le jeu se ferme ou plante au lancement</td><td>Suis la fenêtre « Minecraft a planté ». Sinon, désactive les derniers mods ajoutés (interrupteur dans Installés) et relance. Si ça remarche, réactive-les un par un pour trouver le coupable.</td></tr><tr><td>« Mod incompatible », « requires … »</td><td>Un mod n&#39;est pas fait pour ta version ou ton loader, ou il lui manque un autre mod. Clique <strong>Tout mettre à jour</strong>, sinon retire-le.</td></tr><tr><td>Le jeu rame</td><td>Installe <strong>Sodium</strong>. Avec des shaders, choisis-en un plus léger ou désactive-les (Échap → Options → Shader packs).</td></tr><tr><td>« Out of memory », le jeu fige puis crashe</td><td>Monte un peu la RAM dans ⚙ Gérer (par exemple 4 → 6 Go), sans dépasser la moitié de celle du PC.</td></tr><tr><td>Impossible de rejoindre un pote</td><td>Même version, même loader, mêmes mods : le plus simple est qu&#39;il t&#39;envoie son <code>.kpack</code>.</td></tr><tr><td>Mon skin ne s&#39;affiche pas</td><td>Vérifie que l&#39;instance a un loader (pas Vanilla) et que « Skins Kodus » est coché dans ⚙ Gérer. Un nouveau skin peut mettre une minute à apparaître.</td></tr><tr><td>« Ce pseudo est déjà réservé »</td><td>Quelqu&#39;un a déjà un skin avec ce pseudo. Choisis-en un autre, ou demande à l&#39;admin si c&#39;est le tien (changement de PC).</td></tr><tr><td>Windows bloque l&#39;installation</td><td>Voir <a href="./installer">Installer Kodus</a> : « Exécuter quand même », ou la version portable.</td></tr><tr><td>Kodus ne s&#39;ouvre pas sur Mac</td><td>Il faut macOS 13 ou plus récent, voir <a href="./installer#sur-mac">Installer Kodus</a>.</td></tr><tr><td>Le premier lancement est très long</td><td>Normal : Java et le jeu se téléchargent une fois. Regarde la barre de progression.</td></tr></tbody></table><h2 id="demander-de-l-aide" tabindex="-1">Demander de l&#39;aide <a class="header-anchor" href="#demander-de-l-aide" aria-label="Permalink to &quot;Demander de l&#39;aide&quot;">​</a></h2><p>Si rien ne marche, envoie les logs à l&#39;admin : page de l&#39;instance → onglet <strong>Logs</strong> → <strong>Copier</strong>, puis colle-les dans un message. Dis aussi ce que tu faisais quand ça a planté (et quel mod tu venais d&#39;ajouter).</p>',10)])])}const g=t(s,[["render",o]]);export{m as __pageData,g as default};
